{
  "technical_and_design_decisions": [
    "For U1 and U2, refactoring of the statebased and entities packages will replace internal fabric utility usage with standalone or standard library implementations, ensuring only fabric protobuf packages remain as fabric imports to meet acceptance criteria.",
    "For U5-U8, each requested component (protoutil, BCCSP, MSP, discovery client) will be extracted into a separate, versioned Go module under the fabric-lib-go repository, with unnecessary internal fabric dependencies removed and public APIs maintained for backward compatibility with downstream SDK users.",
    "For U3 and U4, the marbles02_private tutorial fix will be applied directly to the example chaincode export commands and associated documentation in the fabric-samples repository, adding the tr -d \\ step to strip newline characters from base64-encoded JSON inputs.",
    "All refactoring and externalization work will be validated using existing component test suites and dependency checks (via go list) to confirm no unintended fabric dependencies remain in modified packages, and that externalized modules have no unnecessary internal dependencies."
  ],
  "assumptions": [
    "Existing test suites for all affected components (statebased, entities, protoutil, BCCSP, MSP, discovery client) are available and pass prior to changes, and can be used to validate that refactoring/externalization does not break existing functionality.",
    "The fabric-protos-go module is already published and available as a public dependency, so no work is required to externalize protobuf definitions as part of this increment.",
    "The marbles02_private chaincode example and its associated tutorial documentation are hosted in the public fabric-samples repository and can be modified directly as part of this increment.",
    "No functional changes to the externalized components are required, only extraction into standalone modules and removal of unnecessary internal dependencies.",
    "No SDK migration work is included in scope; existing SDK consumers will be responsible for migrating to the new standalone externalized modules on their own timeline.",
    "All new externalized modules will be published to the public Go module proxy under the github.com/hyperledger organization, with no additional infrastructure work required."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Refactor statebased package to remove non-proto fabric dependencies",
      "activity_description": "Modify the core/chaincode/shim/ext/statebased package to eliminate all imports of internal fabric packages except fabric protos, replace any internal utility usage with standalone or standard library equivalents, run existing tests, and validate via go list that only protos are imported per U1 acceptance criteria.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Refactor entities package to remove all fabric dependencies",
      "activity_description": "Modify the core/chaincode/shim/ext/entities/... packages to eliminate all imports of internal fabric packages, replace any required utility functionality with standalone implementations, run existing tests, and validate via go list that no fabric packages are dependencies per U2 acceptance criteria.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Update marbles02_private tutorial and example export commands",
      "activity_description": "Modify the marbles02_private chaincode example in fabric-samples and its associated tutorial documentation to add the tr -d \\ step to export commands for marble JSON variables, eliminating newline characters that cause JSON parsing errors on Windows hosts as reported in U3 and U4.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize protoutil to fabric-lib-go module",
      "activity_description": "Extract the protoutil package from the core fabric repository into a standalone, versioned Go module under fabric-lib-go, remove unnecessary internal fabric dependencies, maintain public API compatibility for existing SDK consumers, run full test suite, and publish the module to meet U5 requirements.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize BCCSP to fabric-lib-go module",
      "activity_description": "Extract the BCCSP package and its required subpackages (factory, sw, idemix, etc.) from the core fabric repository into a standalone fabric-lib-go module, remove unnecessary internal dependencies, maintain API compatibility, run full test suite, and publish the module to meet U6 requirements.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize MSP to fabric-lib-go module",
      "activity_description": "Extract the MSP package and its required subpackages from the core fabric repository into a standalone fabric-lib-go module, remove unnecessary internal dependencies, maintain API compatibility, run full test suite, and publish the module to meet U7 requirements.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize discovery client to fabric-lib-go module",
      "activity_description": "Extract the discovery client package from the core fabric repository into a standalone fabric-lib-go module, remove unnecessary internal dependencies, maintain API compatibility, run full test suite, and publish the module to meet U8 requirements.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 26
  }
}

